declare namespace local="http://www.example.com";
declare variable $x := 1;
declare function local:val() as xs:int{
  xs:int(78 + $x)
};
	declare variable $state := local:val();
     if ($state = (14,                           (: QName^Token :)
                        69,                           (: 'after' :)
                        71,                           (: 'ancestor' :)
                        72,                           (: 'ancestor-or-self' :)
                        73,                           (: 'and' :)
                        74,                           (: 'as' :)
                        75,                           (: 'ascending' :)
                        79,                           (: 'before' :)
                        82,                           (: 'case' :)
                        83,                           (: 'cast' :)
                        84,                           (: 'castable' :)
                         207,                          (: 'with' :)
                        208)) then
let $state := sum(1 to 5)
return $state
else $state

 declare namespace local="http://www.example.com";
 declare variable $x := 70;
 declare function local:val($y){
   xs:int(79+$y)
 };
 	declare variable $state := local:val($x);
       if ($state = 1                                   (: IntegerLiteral :)
or $state = 2                                   (: DecimalLiteral :)
or $state = 3                                   (: DoubleLiteral :)
or $state = 4                                   (: StringLiteral :)
or $state = 30                                  (: '$' :)
or $state = 31                                  (: '%' :)
or $state = 33                                  (: '(' :)
or $state = 42                                  (: '.' :)
or $state = 51                                  (: '<' :)
or $state = 52                                  (: '<!--' :)
or $state = 57                                  (: '<?' :)
or $state = 1357
or $state = 13815211                            (: 'processing-instruction' 'where' '{' :)
or $state = 13815629                            (: 'attribute' 'with' '{' :)
or $state = 13815658                            (: 'element' 'with' '{' :)
or $state = 13815700                            (: 'namespace' 'with' '{' :)
or $state = 13815723) then
 let $state := sum(1 to 5)
 return $state
 else $state

